function Shell({children,lang,setLang}:{children:React.ReactNode,lang:Lang,setLang:(l:Lang)=>void}){const [open,setOpen]=useState(false);const location=useLocation();const c=copy[lang];const homeLabels:Record<Lang,string>={EN:'Home',PL:'Start',RU:'Главная',DE:'Startseite',FR:'Accueil',ES:'Inicio'};const links=[['/wellness',c.nav[0]],['/sri-lanka',c.nav[1]],['/dr-vipula.html',c.nav[2]],['/reiki',c.nav[3]],['/about',c.nav[4]]] as const;const close=()=>setOpen(false);const isActive=(path:string)=>path==='/'?location.pathname==='/':location.pathname===path||location.pathname.startsWith(path+'/');return <><header className="siteHeader"><Link className="brand" to="/" onClick={close}><span className="mark"><Leaf/></span><span>CEYLON WELLNESS<small>{publicText(lang,'brandTagline')}</small></span></Link><button className="menu" aria-label={open?"Close navigation":"Open navigation"} aria-expanded={open} onClick={()=>setOpen(!open)}>{open?<X/>:<Menu/>}</button><nav className={open?'open':''}><Link className={isActive('/')?'active':''} to="/" onClick={close}>{homeLabels[lang]}</Link>{links.map(([path,label])=>path==='/dr-vipula.html'?<a href={path} key={path} onClick={close}>{label}</a>:<Link className={isActive(path)?'active':''} to={path} key={path} onClick={close}>{label}</Link>)}<label className="lang"><Languages/><select value={lang} onChange={e=>{setLang(e.target.value as Lang);close();}}>{LANGS.map(l=><option key={l}>{l}</option>)}</select></label><Link className="pill" to="/ask-ceylon" onClick={close}><Sparkles/> {c.ask}</Link></nav></header>{children}<footer><div><b>CEYLON WELLNESS</b><p>{publicText(lang,'footerIntro')}</p></div><div><b>{publicText(lang,'explore')}</b><Link to="/ask-ceylon">{c.ask}</Link><Link to="/sri-lanka">{c.nav[1]}</Link><Link to="/reiki">{publicText(lang,'reikiRole')}</Link><a href="/dr-vipula.html">Dr. Vipula</a></div><div><b>{publicText(lang,'contact')}</b><a href={wa(c.public?.humanMessage||'Hello Ceylon Wellness.')} target="_blank" rel="noreferrer">{publicText(lang,'whatsapp')} {PRIMARY.phone}</a><Link to="/privacy">{publicText(lang,'privacy')}</Link></div><small>© {new Date().getFullYear()} Ceylon Wellness · {publicText(lang,'wellnessNotice')}</small></footer><a className="waFloat" href={wa(c.public?.humanMessage||'Hello Ceylon Wellness.')} target="_blank" rel="noreferrer"><MessageCircle/><span>{publicText(lang,'whatsapp')}</span></a></>}
const CTA=({lang}:{lang:Lang})=> <section className="cta"><div><span className="eyebrow">{publicText(lang,'ctaEyebrow')}</span><h2>{publicText(lang,'ctaHeading')}</h2><p>{publicText(lang,'ctaDescription')}</p></div><a className="button light" href={wa(copy[lang].public?.humanMessage||'Hello Ceylon Wellness.')} target="_blank">{publicText(lang,'ctaButton')} <ArrowRight/></a></section>;

