function SriLankaGuide({lang}:{lang:Lang}){
  const c=SRI_LANKA_PAGE_COPY[lang];
  const [region,setRegion]=useState('All');
  const regions=['All',...Array.from(new Set(SRI_LANKA_PLACES.map(p=>p.region)))];
  const shown=region==='All'?SRI_LANKA_PLACES:SRI_LANKA_PLACES.filter(p=>p.region===region);
  const regionLabel:Record<string,Record<string,string>>={
    All:{EN:'All places',PL:'Wszystkie',RU:'Все места',DE:'Alle',FR:'Tous',ES:'Todos'},
    'Cultural Heart':{EN:'Cultural Heart',PL:'Serce kultury',RU:'Культурное сердце',DE:'Kulturelles Herz',FR:'Cœur culturel',ES:'Corazón cultural'},
    'Hill Country':{EN:'Hill Country',PL:'Kraina gór',RU:'Горная местность',DE:'Bergland',FR:'Hautes terres',ES:'Tierras altas'},
    'Wildlife & Nature':{EN:'Wildlife & Nature',PL:'Dzika przyroda i natura',RU:'Дикая природа',DE:'Wildnis & Natur',FR:'Faune & nature',ES:'Fauna y naturaleza'},
    'South Coast':{EN:'South Coast',PL:'Południowe wybrzeże',RU:'Южное побережье',DE:'Südküste',FR:'Côte sud',ES:'Costa sur'},
    'East Coast':{EN:'East Coast',PL:'Wschodnie wybrzeże',RU:'Восточное побережье',DE:'Ostküste',FR:'Côte est',ES:'Costa este'},
    City:{EN:'City',PL:'Miasto',RU:'Город',DE:'Stadt',FR:'Ville',ES:'Ciudad'}
  };
  return <main className="sriGuidePage">
    <section className="sriGuideHero">
      <div className="sriGuideHeroGlow"/>
      <div className="sriGuideHeroContent">
        <span className="eyebrow">{c.eyebrow}</span>
        <h1>{c.title}</h1>
        <p>{c.intro}</p>
        <div className="sriGuideHeroActions"><Link className="button light" to="/ask-ceylon"><Sparkles/> Ask Ceylon <ArrowRight/></Link><a className="sriBackLink" href="#sri-places"><ArrowLeft/> {c.explore}</a></div>
      </div>
      <div className="sriGuideHeroImage"><img src={DESTINATION_META['Sigiriya'].image} alt="Sigiriya, Sri Lanka"/></div>
    </section>

    <section className="sriGuideIntro" id="sri-places">
      <div><span className="eyebrow">{c.regionLabel}</span><h2>{c.explore}</h2></div>
      <p>18 destinations · cultural heritage · hill country · wildlife · rainforest · coast · city</p>
    </section>

    <div className="sriRegionFilters" aria-label={c.regionLabel}>
      {regions.map(r=><button key={r} type="button" className={region===r?'active':''} onClick={()=>setRegion(r)}>{regionLabel[r]?.[lang]||r}</button>)}
    </div>

    <section className="sriPlaceGrid" aria-label={c.explore}>
      {shown.map((place,i)=><article className="sriPlaceCard" key={place.name} id={`destination-${place.name.toLowerCase().replace(/[^a-z0-9]+/g,'-')}`}>
        <div className="sriPlaceImage"><img src={place.image} alt={`${place.name}, Sri Lanka`} loading="lazy"/><span className="sriPlaceNo">{String(SRI_LANKA_PLACES.findIndex(x=>x.name===place.name)+1).padStart(2,'0')}</span><span className="sriPlaceRegion">{regionLabel[place.region]?.[lang]||place.region}</span></div>
        <div className="sriPlaceBody"><h3>{place.name}</h3><p className="sriPlaceDescription">{place.description}</p><div className="sriPlaceHighlights">{place.highlights.map(h=><span key={h}><CheckCircle2/>{h}</span>)}</div><div className="sriPlaceWellness"><span className="eyebrow">CEYLON WELLNESS</span><p>{place.wellness}</p></div><Link className="sriPlaceCTA" to="/ask-ceylon">{c.plan}<ArrowRight/></Link></div>
      </article>)}
    </section>

    <section className="sriGuideFinal"><div><span className="eyebrow">{c.eyebrow}</span><h2>{c.title}</h2><p>{c.intro}</p></div><Link className="button" to="/ask-ceylon"><Sparkles/> Ask Ceylon <ArrowRight/></Link></section>
    <div className="sriGuideBackHome"><Link to="/"><ArrowLeft/> {c.back}</Link></div>
  </main>;
}

